{
  "title": "Area and integrals: quick check",
  "intro": "Four questions. Take your time, then press **Check my answers**.",
  "questions": [
    {"question": "What is $\\int_0^1 x\\,dx$?", "options": ["$0$", "$\\tfrac{1}{2}$", "$1$", "$2$"], "answer": 1, "explanation": "Under $y = x$ from 0 to 1 is a triangle with base 1 and height 1: area $\\tfrac{1}{2}$."},
    {"question": "Which is an antiderivative of $2x$?", "options": ["$2$", "$x^2$", "$2x^2$", "$\\tfrac{x}{2}$"], "answer": 1, "explanation": "The derivative of $x^2$ is $2x$, so $x^2$ (plus any constant) is an antiderivative."},
    {"question": "If $f(x) < 0$ on $[a,b]$, then $\\int_a^b f(x)\\,dx$ is…", "options": ["positive", "zero", "negative"], "answer": 2, "explanation": "Area below the x-axis counts as negative in a definite integral."},
    {"question": "Why do we write $+C$ in $\\int 2x\\,dx = x^2 + C$?", "options": ["It is a typo", "Constants have derivative 0, so any constant works", "C stands for curve"], "answer": 1, "explanation": "$x^2 + 5$ and $x^2 - 3$ both have derivative $2x$. The $+C$ says every one of them is an answer."}
  ]
}
